// What packages ask of the process around them, as Node.js answers it: the report header's libc
// fields (prebuilt addons pick their build by them), paths of files that aren't modules (a
// platform package's .so or .wasm), and WebAssembly compiled with nothing else keeping the
// program running.
import { createRequire } from "node:module"

export async function run() {
  const header = process.report.getReport().header
  const glibc = header.glibcVersionRuntime
  console.log("report header", header.platform === process.platform, header.arch === process.arch)
  console.log("libc", process.platform !== "linux" ? glibc === undefined : glibc === undefined || /^\d+\.\d+$/.test(glibc))

  const require = createRequire(import.meta.url)
  const so = require.resolve("fake-native-lib/lib.so")
  console.log("require.resolve", so.endsWith("/node_modules/fake-native-lib/lib.so"))
  console.log("import.meta.resolve", import.meta.resolve("fake-native-lib/lib.so") === "file://" + so)
  try {
    require.resolve("fake-native-lib/missing.so")
  } catch (e) {
    console.log("missing", e.code)
  }

  // (no timer: only the compile, on the engine's threads, is left for the program to wait for)
  const bytes = new Uint8Array([0, 97, 115, 109, 1, 0, 0, 0, 1, 7, 1, 96, 2, 127, 127, 1, 127, 3, 2, 1, 0, 7, 7, 1, 3, 97, 100, 100, 0, 0, 10, 9, 1, 7, 0, 32, 0, 32, 1, 106, 11]);
  const { instance } = await WebAssembly.instantiate(bytes)
  console.log("wasm add", instance.exports.add(2, 3))
}
